package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.CategoryDAO; import com.example.ecommerce.model.Category; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/categories") public class AdminCategoryServlet extends HttpServlet{CategoryDAO dao=new CategoryDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String action=req.getParameter("action");if("edit".equals(action))req.setAttribute("category",dao.findById(Integer.parseInt(req.getParameter("id"))));if("delete".equals(action)){dao.deactivate(Integer.parseInt(req.getParameter("id")));resp.sendRedirect(req.getContextPath()+"/admin/categories");return;}req.setAttribute("categories",dao.findAll());req.getRequestDispatcher("/WEB-INF/views/admin/categories.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{Category c=new Category();String id=req.getParameter("id");if(id!=null&&!id.isEmpty())c.setId(Integer.parseInt(id));c.setName(req.getParameter("name"));c.setDescription(req.getParameter("description"));c.setActive("on".equals(req.getParameter("active")));dao.save(c);resp.sendRedirect(req.getContextPath()+"/admin/categories");}catch(Exception e){throw new ServletException(e);}}}
